public class IntegerTupleSketchValueAggregator implements ValueAggregator<byte[], Object> {
  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;

  private final IntegerSummary.Mode _mode;
  private final int _nominalEntries;
  // Static upper bound on the serialized size of a Tuple sketch with the configured nominal entries. Each retained
  // entry uses 8 bytes for the hash and 4 bytes for the IntegerSummary, plus a fixed serialization header.
  private final int _maxByteSize;

  public IntegerTupleSketchValueAggregator(IntegerSummary.Mode mode) {
    _mode = mode;
    _nominalEntries = 1 << CommonConstants.Helix.DEFAULT_TUPLE_SKETCH_LGK;
    _maxByteSize = 24 + _nominalEntries * (Long.BYTES + Integer.BYTES);
  }

  @Override
  public AggregationFunctionType getAggregationType() {
    return AggregationFunctionType.DISTINCTCOUNTTUPLESKETCH;
  }

  @Override
  public DataType getAggregatedValueType() {
    return AGGREGATED_VALUE_TYPE;
  }

  // Utility method to create a new Union with the configured nominal entries
  private Union<IntegerSummary> newUnion() {
    return new Union<>(_nominalEntries, new IntegerSummarySetOperations(_mode, _mode));
  }

  // The aggregated value can either be a Union (used to accumulate intermediate results efficiently) or a
  // Sketch<IntegerSummary> (the deserialized form).
  @Override
  public Object getInitialAggregatedValue(byte[] rawValue) {
    return deserializeSketch(rawValue);
  }

  @Override
  public Object applyRawValue(Object value, byte[] rawValue) {
    Union<IntegerSummary> union = extractUnion(value);
    union.union(deserializeSketch(rawValue));
    return union;
  }

  @Override
  public Object applyAggregatedValue(Object value, Object aggregatedValue) {
    Union<IntegerSummary> union = extractUnion(value);
    union.union(extractSketch(aggregatedValue));
    return union;
  }

  @Override
  public Object cloneAggregatedValue(Object value) {
    return deserializeSketch(serializeAggregatedValue(value));
  }

  @Override
  public int getMaxAggregatedValueByteSize() {
    return _maxByteSize;
  }

  @Override
  public byte[] serializeAggregatedValue(Object value) {
    return CustomSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.serialize(extractSketch(value));
  }

  @Override
  public Object deserializeAggregatedValue(byte[] bytes) {
    return deserializeSketch(bytes);
  }

  private Sketch<IntegerSummary> deserializeSketch(byte[] bytes) {
    return CustomSerDeUtils.DATA_SKETCH_INT_TUPLE_SER_DE.deserialize(bytes);
  }

  // Reuses the union if the value is already a Union, otherwise wraps the Sketch in a new Union.
  private Union<IntegerSummary> extractUnion(Object value) {
    if (value instanceof Union) {
      //noinspection unchecked
      return (Union<IntegerSummary>) value;
    }
    Union<IntegerSummary> union = newUnion();
    //noinspection unchecked
    union.union((Sketch<IntegerSummary>) value);
    return union;
  }

  @SuppressWarnings("unchecked")
  private Sketch<IntegerSummary> extractSketch(Object value) {
    if (value instanceof Union) {
      return ((Union<IntegerSummary>) value).getResult();
    }
    return (Sketch<IntegerSummary>) value;
  }
